import numpy as np
from scipy.optimize import fsolve

def equations(p):
    x, y, z = p
    eq1 = x**2 + y**2 + z**2 - 3
    eq2 = x*y**3 + y*z**3 + z*x**3 - 3
    return [eq1, eq2]

# We have 2 equations and 3 variables. This defines a curve in 3D.
# Let's fix x and solve for y and z.
def find_solutions_fixed_x():
    solutions = []
    for x_fixed in np.linspace(-1.8, 1.8, 40):
        def equations_fixed_x(p):
            y, z = p
            eq1 = x_fixed**2 + y**2 + z**2 - 3
            eq2 = x_fixed*y**3 + y*z**3 + z*x_fixed**3 - 3
            return [eq1, eq2]

        # Try multiple starting points for (y, z)
        for y_start in np.linspace(-1.8, 1.8, 5):
            for z_start in np.linspace(-1.8, 1.8, 5):
                sol, info, ier, msg = fsolve(equations_fixed_x, [y_start, z_start], full_output=True)
                if ier == 1:
                    y, z = sol
                    if np.isclose(x_fixed**2 + y**2 + z**2, 3) and np.isclose(x_fixed*y**3 + y*z**3 + z*x_fixed**3, 3):
                        solutions.append((x_fixed, y, z))

    # Filter unique solutions
    unique_solutions = []
    for s in solutions:
        if not any(np.allclose(s, us, atol=1e-3) for us in unique_solutions):
            unique_solutions.append(s)

    return unique_solutions

print(find_solutions_fixed_x())

import numpy as np
from scipy.optimize import fsolve

def equations(p):
    x, y, z = p
    eq1 = y**3 + 3*z*x**2 - 4*x
    eq2 = 3*x*y**2 + z**3 - 4*y
    eq3 = 3*y*z**2 + x**3 - 4*z
    return [eq1, eq2, eq3]

solutions = []
for x0 in np.linspace(-2, 2, 10):
    for y0 in np.linspace(-2, 2, 10):
        for z0 in np.linspace(-2, 2, 10):
            sol, info, ier, msg = fsolve(equations, [x0, y0, z0], full_output=True)
            if ier == 1:
                x, y, z = sol
                if np.isclose(x**2 + y**2 + z**2, 3, atol=1e-3):
                    solutions.append((x, y, z))

unique_solutions = []
for s in solutions:
    if not any(np.allclose(s, us, atol=1e-3) for us in unique_solutions):
        unique_solutions.append(s)

print("Critical points on the sphere:", unique_solutions)

# Now check the value of g = x*y^3 + y*z^3 + z*x^3 at these points
for s in unique_solutions:
    x, y, z = s
    g = x*y**3 + y*z**3 + z*x**3
    print(f"Point: ({x:.4f}, {y:.4f}, {z:.4f}), g = {g:.4f}")

