import numpy as np
from scipy.optimize import minimize

def objective(p):
    x, y, z = p
    return -(x*y**3 + y*z**3 + z*x**3)

def constraint(p):
    return p[0]**2 + p[1]**2 + p[2]**2 - 3

def find_max():
    max_val = -np.inf
    # Try many starting points
    for _ in range(100):
        start_point = np.random.rand(3) * 4 - 2
        # Normalize the starting point to be on the sphere
        start_point = start_point / np.linalg.norm(start_point)
        start_point *= np.sqrt(3)

        res = minimize(objective, start_point, constraints={'type': 'eq', 'fun': constraint}, method='SLSQP', tol=1e-12)
        if -res.fun > max_val:
            max_val = -res.fun

    return max_val

print(f"Maximum value: {find_max()}")

